-- munis con gastronomía curada (platos/productos) pero sin score: base 25
INSERT INTO puntuaciones(codigo_ine,categoria,puntuacion)
SELECT DISTINCT e.codigo_ine,'gastronomia',25 FROM entidades e JOIN municipios m ON m.codigo_ine=e.codigo_ine
WHERE e.tipo IN ('gastronomia','producto') AND COALESCE(m.es_duplicado,0)=0
ON CONFLICT(codigo_ine,categoria) DO UPDATE SET puntuacion=MAX(puntuacion,excluded.puntuacion);
